# @generated by usage-cli from occam.usage.kdl
# Requires bash-completion (https://github.com/scop/bash-completion), which must be
# sourced before this script.
_occam() {
    if ! type -P usage &> /dev/null; then
        echo >&2
        echo "Error: usage CLI not found. This is required for completions to work in occam." >&2
        echo "See https://usage.jdx.dev for more information." >&2
        return 1
    fi
    if ! declare -F _init_completion > /dev/null 2>&1; then
        echo >&2
        echo "Error: bash-completion is required for occam completions but was not loaded." >&2
        echo "Install it from your package manager and source it before this script." >&2
        return 1
    fi

	local cur prev words cword comp_args
    # `=` and `:` stay inside the word so complete-word sees `--out=a` as one word
    # rather than `--out`, `=`, `a`.
    _init_completion -n := -- "$@" || return
    local spec_dir="${XDG_CACHE_HOME:-$HOME/.cache}/usage"
    [[ -d "$spec_dir" ]] || mkdir -p -m 700 "$spec_dir"
    local spec_file="$spec_dir/usage__usage_spec_occam.spec"
    cat >| "$spec_file" <<'__USAGE_EOF__'
name Occam
bin occam
version "0.1.0"
about "Occam: Dependency-Aware Multi-Statement SQL Test Case Minimizer"
flag --oracle help="Interestingness predicate command (SQL on stdin; exit 0 accepts)" required=#true {
    arg <COMMAND>
}
flag "-o --out" help="Directory where reduced artifacts will be written, or '-' for stdout" default=occam-out {
    arg <DIR>
}
flag --reset help="Lightweight state reset command (e.g. dropdb/createdb or custom reset script)" {
    arg <COMMAND>
}
flag --timeout help="Per-execution timeout in seconds for each oracle run" default="10.0" {
    arg <SECONDS>
}
flag --log-level help="Log severity level" default=info {
    arg <LEVEL> {
        choices {
            choice debug help="Verbose diagnostic and internal graph transition logging"
            choice info help="Informational milestones, reduction steps, and summaries (default)"
            choice warn help="Warnings and non-fatal oracle or parse anomalies"
            choice error help="Fatal errors and test failures only"
        }
    }
}
flag --log-format help="Log output format" default=text {
    arg <FORMAT> {
        choices {
            choice text help="Human-readable text logs with timestamps and component tags (default)"
            choice json help="Structured newline-delimited JSON logs for pipelines"
        }
    }
}
flag "-v --verbose" help="Enable verbose debug output (equivalent to --log-level debug)"
flag "-q --quiet" help="Suppress info logs and banners (equivalent to --log-level error)"
flag --usage-spec help="Print CLI usage specification (KDL format for 'usage' shell completion generator)"
flag --version help="Show version information"
flag "-h --help" help="Show help information"
flag --budget help="Shared wall-clock cap including initial check, reduction, and audit" {
    arg <SECONDS>
}
flag --max-oracle-executions help="Maximum uncached oracle attempts including initial check and validation" {
    arg <N>
}
flag --jobs help="Maximum concurrent oracle/reset interactions; values above 1 require independent external state (no DB isolation is promised)" default="1" {
    arg <N>
}
flag --slicing help="Enable backward dependency slicing pass (default: on)"
flag --no-slicing help="Disable backward dependency slicing pass"
flag --closure help="Enable dependency closure minimization pass (default: on)"
flag --no-closure help="Disable dependency closure minimization pass"
flag --intra-statement help="Enable intra-statement AST clause and expression pruning (default: off)"
flag --no-intra-statement help="Disable intra-statement AST clause and expression pruning"
flag --column-mode help="Column co-reduction listing (requires --intra-statement unless off)" default=off {
    arg <MODE> {
        choices {
            choice off help="No column co-reduction (default)"
            choice single help="Per-column single sites"
            choice atomic help="Joint bundles plus identical singles"
        }
    }
}
flag --unrestricted help="Enable unrestricted statement ddmin fallback (default: on)"
flag --no-unrestricted help="Disable unrestricted statement ddmin fallback"
flag --cache help="Enable candidate query hash memoization (default: on)"
flag --no-cache help="Disable candidate query hash memoization"
flag --dialect help="SQL dependency analysis dialect" default=generic {
    arg <DIALECT> {
        choices {
            choice generic help="Generic ANSI SQL with common relational constructs (default)"
            choice postgresql help="PostgreSQL (schemas, dollar quotes, ::type casts, CTEs, RETURNING)"
            choice mysql help="MySQL 8.0 (backticks, version comments, ON DUPLICATE KEY)"
            choice sqlite help="SQLite 3 (WITHOUT ROWID, STRICT mode, savepoints, triggers)"
            choice duckdb help="DuckDB (column references, list/struct comprehensions)"
            choice clickhouse help="ClickHouse (table engines, tuple types, case folding)"
            choice oracle help="Oracle database dialect"
            choice ansi help="Strict ANSI SQL standard"
            choice bigquery help="Google BigQuery dialect"
            choice databricks help="Databricks SQL dialect"
            choice hive help="Apache Hive QL dialect"
            choice mssql help="Microsoft SQL Server (T-SQL) dialect"
            choice redshift help="Amazon Redshift dialect"
            choice snowflake help="Snowflake SQL dialect"
            choice spark help="Apache Spark SQL dialect"
            choice teradata help="Teradata SQL dialect"
        }
    }
}
arg <INPUT.sql> help="Path to fuzz SQL input, or '-' for stdin"
complete input.sql type=file:sql
complete oracle type=command_args
complete out type=dir
complete reset type=command_args
__USAGE_EOF__
    # stderr is discarded: a line that doesn't parse (`occam help <Tab>`) makes
    # complete-word fail, and its error would be printed over the prompt.
    # Complete the text before the cursor, as `$cur` holds it: with the cursor in `--out=a|X`
    # the value typed so far is `a`, not `aX`.
    words[cword]="$cur"
    # One candidate per line, kept as text. `compgen -W` expands every word it is handed
    # (`$(…)`, globs, quote removal), so a candidate printed by a `run=` completer would have
    # run as a command here, and `*` would have become the files in the working directory.
    COMPREPLY=()
    local __usage_line
    while IFS= read -r __usage_line; do
        [[ -n "$__usage_line" && "$__usage_line" == "$cur"* ]] && COMPREPLY+=("$__usage_line")
    done < <(command usage complete-word --shell bash -f "$spec_file" --cword="$cword" -- "${words[@]}" 2>/dev/null)
	# Readline only replaces the text after the last word break, so strip the part of
	# `$cur` up to its last `:` or `=` from each candidate (what __ltrim_colon_completions
	# does for `:` alone).
	local breaks="${COMP_WORDBREAKS//[^:=]/}"
	# An empty COMPREPLY is left alone: before bash 4.4 the rewrite below would turn it into
	# one empty candidate.
	if ((${#COMPREPLY[@]})) && [[ -n "$breaks" && "$cur" == *["$breaks"]* ]]; then
		local break_prefix="${cur%"${cur##*["$breaks"]}"}"
		COMPREPLY=("${COMPREPLY[@]#"$break_prefix"}")
	fi
    # shellcheck disable=SC2181
    if [[ $? -ne 0 ]]; then
        unset COMPREPLY
    fi
    return 0
}

if [[ "${BASH_VERSINFO[0]}" -eq 4 && "${BASH_VERSINFO[1]}" -ge 4 || "${BASH_VERSINFO[0]}" -gt 4 ]]; then
    shopt -u hostcomplete && complete -o nospace -o bashdefault -o nosort -F _occam occam
else
    shopt -u hostcomplete && complete -o nospace -o bashdefault -F _occam occam
fi
